#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

/* Upper bound used by the original program (0xbfa17dc6 = 3 215 031 302) */
#define MAX_VALUE 0xBFA17DC6LL

/* Deterministic Miller–Rabin bases used by the original binary */
static const int64_t bases[] = {2, 3, 5, 7, 11, 13};

/* (a * b) % mod using 128‑bit intermediate to avoid overflow */
static int64_t mul_mod(int64_t a, int64_t b, int64_t mod)
{
    __int128 res = (__int128)a * (__int128)b;
    res %= mod;
    return (int64_t)res;
}

/* (base^exp) % mod */
static int64_t pow_mod(int64_t base, int64_t exp, int64_t mod)
{
    int64_t result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* Miller–Rabin test for a single base */
static int miller_rabin_pass(int64_t n, int64_t a)
{
    int64_t d = n - 1;
    int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    int64_t x = pow_mod(a, d, n);
    if (x == 1 || x == n - 1)
        return 1;

    for (int r = 1; r < s; ++r) {
        x = mul_mod(x, x, n);
        if (x == n - 1)
            return 1;
    }
    return 0;
}

/* Return 1 if n is prime, 0 otherwise (using the fixed bases) */
static int is_prime(int64_t n)
{
    if (n < 2)
        return 0;
    if ((n & 1) == 0)
        return n == 2;

    for (size_t i = 0; i < sizeof(bases) / sizeof(bases[0]); ++i) {
        int64_t a = bases[i];
        if (a >= n)
            break;
        if (!miller_rabin_pass(n, a))
            return 0;
    }
    return 1;
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    int64_t n = strtoll(argv[1], &endptr, 10);

    /* Bad input: strtoll did not consume the whole string */
    if (endptr == NULL || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > MAX_VALUE) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
